/* The vector files the on-chip test runs, in flash (generated by tests/device/bundle.py). */
#ifndef AB_BUNDLE_H
#define AB_BUNDLE_H

#include <stddef.h>

typedef struct {
    const char *name;
    int fmt;                    /* 1: a format-vectors file (fmt_vectors), 0: key vectors */
    const char *text;
    size_t len;
} bundle_file;

extern const bundle_file BUNDLE[];
extern const unsigned BUNDLE_COUNT;

#endif
